<template><p v-if="error" class="wb-notice error">{{error}}</p><template v-if="data"><section class="wb-metrics"><article><label>真实买卖流水</label><strong>{{data.summary.trade_count ?? '—'}}</strong><small>旧系统手工记录</small></article><article><label>旧库未平仓记录</label><strong>{{data.summary.open_records ?? '—'}}</strong><small>不代表当前券商持仓</small></article><article><label>最后一笔交易日期</label><strong>{{data.summary.last_trade_date || '—'}}</strong><small>页面刷新不改动原始记录</small></article><article><label>旧台账已填卖出利润合计</label><strong>{{fmt(data.summary.recorded_profit_sum)}}</strong><small>{{data.summary.sell_records_with_profit}}笔有利润 · 费用未核验</small></article></section><section class="wb-panel"><div class="wb-panel-title"><h3>真实交易档案</h3><div class="wb-mode"><button @click="tab='trades'" :class="{active:tab==='trades'}">买卖流水</button><button @click="tab='holdings'" :class="{active:tab==='holdings'}">持仓档案</button></div></div><p class="wb-footnote">{{data.note}}</p><details v-if="data.reconciliation?.length"><summary>台账核对：{{data.reconciliation.length}}只股票的流水净数量与持仓状态不一致</summary><p v-for="r in data.reconciliation" :key="r.code" class="wb-footnote">{{r.code}}：买卖流水净数 {{r.ledger_net_shares}} 股 / 旧持仓表未平仓 {{r.holding_shares}} 股。可能缺流水或曾修改记录，保留原值待核对。</p></details><div class="wb-table-scroll"><table v-if="tab==='trades'" class="wb-table"><thead><tr><th>原始日期 / 记录时间</th><th>标的</th><th>操作</th><th>成交价</th><th>股数</th><th>旧记录利润</th></tr></thead><tbody><tr v-for="(t,i) in data.trades" :key="i"><td>{{t.trade_date}}<small>{{t.trade_time||'时点未记录'}}</small></td><td><button class="wb-text-button" @click="$emit('stock',t.code)">{{t.name||t.code}} ↗</button><small>{{t.code}}</small></td><td :class="t.action==='buy'?'wb-up':'wb-down'">{{t.action==='buy'?'买入':t.action==='sell'?'卖出':t.action}}</td><td>{{fmt(t.price)}}</td><td>{{t.shares}}</td><td>{{t.action==='sell'?fmt(t.profit):'—'}}</td></tr></tbody></table><table v-else class="wb-table"><thead><tr><th>买入日</th><th>标的</th><th>记录成本</th><th>股数</th><th>旧库状态</th></tr></thead><tbody><tr v-for="(h,i) in data.holdings" :key="i"><td>{{h.buy_date}}</td><td><button class="wb-text-button" @click="$emit('stock',h.code)">{{h.name}} ↗</button><small>{{h.code}}</small></td><td>{{fmt(h.cost)}}</td><td>{{h.shares}}</td><td>{{h.status==='holding'?'未平仓（旧记录）':'已卖出'}}</td></tr></tbody></table></div></section></template></template>
<script setup>
import {ref,onMounted} from 'vue'
import axios from 'axios'
defineEmits(['stock']);const data=ref(),error=ref(''),tab=ref('trades');const fmt=v=>v==null?'—':Number(v).toLocaleString('zh-CN',{maximumFractionDigits:3})
onMounted(async()=>{try{data.value=(await axios.get('/api/workbench/legacy-portfolio')).data;error.value=data.value.error||''}catch{error.value='交易档案读取失败'}})
</script>
